function buildVerificationPipeline(projects) {
  return [
    ...seedPipeline(projects.map(({ projectId }) => ({ projectId }))),
    { $lookup: { from: 'tor_announcements', localField: 'projectId', foreignField: 'projectId', as: 'stored' } },
    { $project: { _id: 0, projectId: 1, projectExists: { $gt: [{ $size: '$stored' }, 0] }, aiProcessing: { $arrayElemAt: ['$stored.aiProcessing', 0] }, tagAssignments: { $ifNull: [{ $arrayElemAt: ['$stored.tagAssignments', 0] }, []] } } },
    { $lookup: { from: 'tags', localField: 'tagAssignments.tagId', foreignField: '_id', as: 'tags' } },
    { $project: { projectId: 1, projectExists: 1, aiProcessing: 1, tagAssignments: 1, totalAssignments: { $size: '$tagAssignments' }, tags: { $map: { input: '$tags', as: 'tag', in: { tagId: { $toString: '$$tag._id' }, text: { $ifNull: ['$$tag.text', '$$tag.name'] }, name: '$$tag.name', category: '$$tag.category', type: '$$tag.type' } } } } }
  ];
}

const { projects } = $('Parse AI and Build Tag Writes').first().json;
return [{ json: { verificationPipeline: buildVerificationPipeline(projects) } }];
